INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'Any object thrown, kicked, or launched into the air and acted on only by gravity and air resistance is called a:', 'Linear object', 'Stationary body', 'Circular object', 'Projectile', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'The curved path a projectile follows through the air is its:', 'Trajectory', 'Radius', 'Slope', 'Axis', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'The two independent motions that combine to make projectile motion are:', 'Up and down only', 'Constant horizontal motion + accelerated vertical free-fall motion', 'Left and right only', 'Fast and slow motion', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'If you kick a football with the same force, which angle will make it go the farthest horizontal distance (maximum range) on flat ground?', '75°', '45°', '15°', '30°', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'If you want a basketball shot to go as high as possible into the air, you should release it at an angle closest to:', '45°', '90° (straight up)', '30°', '0° (horizontal)', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'If you throw a ball horizontally and drop another identical ball from the same height at the same time, which hits the ground first?', 'Thrown ball hits first', 'Dropped ball hits first', 'Both hit at exactly the same time', 'Depends on color', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'The horizontal distance a projectile travels from launch to landing is its:', 'Trajectory', 'Range', 'Height', 'Velocity', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'The maximum vertical distance the projectile reaches above launch level is its:', 'Maximum height', 'Trajectory', 'Range', 'Angle', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'If you shoot two basketballs at the same angle, the one thrown with more speed will have:', 'Same range and height', 'Less height only', 'Shorter range only', 'Both longer range and greater height', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'When air resistance is ignored, the only force acting on a projectile after release is:', 'Wind forward', 'Magnetism', 'Gravity (pulling downward)', 'Your hand', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'A sepak takraw player kicks the ball at 30°, another kicks at the same speed at 60°. Their ranges will be:', '60° goes twice as far', '30° goes farther', 'Both fall at the same spot as 45°', 'Almost exactly equal (complementary angles)', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'Between the same two complementary kicks above, which one reaches a higher maximum height?', 'Same height', '60° kick', 'Neither rises', '30° kick', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'Why does a basketball player use a high arc (large angle) when shooting from far away?', 'To give the ball more time in the air to reach the hoop and enter the ring from above', 'To use less force', 'To avoid gravity', 'To make it go faster', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'If you kick a football at 20° and another at 70° with the same speed, which has the shortest time of flight?', 'Same time', '20° kick', '70° kick', 'Both stay forever', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'pre_test', 'A projectile''s horizontal velocity component (ignoring air resistance) during flight:', 'Becomes zero at the top', 'Decreases due to gravity', 'Stays exactly constant', 'Increases due to gravity', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'A projectile''s vertical velocity component at the exact top of its arc is:', 'Maximum upward', 'Equal to launch speed', 'Maximum downward', 'Zero (momentarily stops going up)', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'In real life (with air resistance), a real football''s actual range compared to the ideal physics prediction will be:', 'Slightly shorter', 'Exactly the same', 'Longer', 'Twice as far', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'A long jumper wants maximum range. What combination should they aim for?', 'Very low angle only', 'Fast run-up + launch angle near 45°', 'Jump straight up', 'Very high angle only', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'If you double the launch speed of a projectile at 45°, its range becomes approximately:', 'Same', '2× longer', '4× longer', '8× longer', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'Two identical stones are thrown: A at 10 m/s, 45°; B at 20 m/s, 45°. Which statement is true?', 'Same flight time', 'B goes 4× farther, about 4× higher, and about 2× longer in the air', 'Same range', 'Same maximum height', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'Which is the correct full relationship among the four projectile variables?', 'Mass of the object is the biggest factor', 'Range and height depend on both launch speed and launch angle through horizontal and vertical velocity', 'Only speed matters', 'Only angle matters', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'At what point in a projectile''s full flight is its total speed slowest?', 'Same speed everywhere', 'At the very peak (top of the trajectory)', 'Right after launch', 'Right before landing', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'A basketball is released and lands at the same height. At what two points in its path is its speed exactly equal?', 'Launch vs. top', 'Never equal', 'Any two points at the same height (e.g., halfway up and halfway down)', 'Top vs. landing', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'Why do professional archers aim slightly above the target even at short distances?', 'To make it go faster', 'Wind always blows up', 'Gravity pulls the arrow downward during flight, so they must compensate for the drop', 'Tradition', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'If you launch from ground level, which pair of angles will give the same range but very different heights and flight times?', '10° and 20°', '40° and 50°', '25° and 65°', 'Both B and C', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'A boy kicks a ball horizontally off a 10 m cliff while another drops an identical ball from the same height at the same instant. Which hits first?', 'Kicked ball first', 'Both hit the ground at exactly the same time', 'Kicked ball never lands', 'Dropped ball first', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'For a fixed launch speed, as angle increases from 0° → 45° → 90°, how do range and height change?', 'Both always decrease', 'Range constant; height rises', 'Range rises to a maximum at 45° then falls; height keeps increasing to 90°', 'Both always increase', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'The only reason 45° gives maximum range on flat ground is:', 'Air resistance is zero only at 45°', 'Gravity is strongest there', 'It perfectly balances time of flight and horizontal speed so their product is maximized', 'It is the middle number', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'In a projectile investigation using a marble launcher, a student keeps the angle fixed at 45° and increases compression (speed) each trial. They will observe:', 'Range stays the same', 'Height stays the same', 'Range increases linearly', 'Range increases roughly as the square of the compression distance', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000301', 1, 'post_test', 'Which everyday action is *NOT* an example of projectile motion?', 'Driving a car in a straight flat road at constant speed', 'Throwing a frisbee (ignoring lift)', 'Kicking a penalty', 'Shooting a three-pointer', 'A', 'Option A is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Momentum is defined mathematically as:', 'Mass × acceleration', 'Mass × velocity (p = m × v)', 'Force × distance', 'Weight × height', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Momentum describes in physics what we mean in everyday life when we say:', 'An object is hot', 'An object is bright', 'A moving object is hard to stop', 'An object is heavy', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Which has more momentum: a slow truck or a fast bullet?', 'Always the truck', 'Depends on BOTH mass AND velocity of each', 'Always the bullet', 'They always have equal momentum', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'A collision where objects bounce off perfectly with no kinetic energy lost is called:', 'Inelastic', 'Explosion', 'Elastic', 'Plastic', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'A collision where objects stick together or deform, losing kinetic energy to heat and sound, is called:', 'Perfect rebound', 'Inelastic', 'Conservative', 'Elastic', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'The Law of Conservation of Momentum says that if no outside force acts, total momentum before collision equals:', 'Zero always', 'Double before', 'Half before', 'Total momentum after collision', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'To change an object''s momentum, you must apply:', 'A net force acting for some amount of time', 'Heat', 'Only mass', 'Only light', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Seatbelts, airbags, and crumple zones all reduce injury mainly by:', 'Making the car lighter', 'Increasing force', 'Increasing the stopping time, lowering the average force', 'Stopping instantly', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'If two identical jeepneys move at different speeds, the faster one has:', 'Same momentum', 'More momentum', 'Zero momentum', 'Less momentum', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'When a moving billiard ball hits a stationary identical ball head-on and stops, the target ball:', 'Explodes', 'Moves away with almost exactly the original ball''s speed', 'Also stays still', 'Moves twice as fast', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Which is the best everyday example of an almost elastic collision?', 'Two train cars coupling together', 'Two billiard balls colliding on a table', 'Car hitting a wall', 'A ball of clay hitting the floor', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Which is the best everyday example of a perfectly inelastic collision?', 'Two train cars bump and lock together moving as one', 'Marbles colliding', 'Superball bouncing', 'Tennis ball on a racket', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'A 2000-kg jeepney and a 200-kg motorcycle both move at 10 m/s. Which is harder to stop?', 'Equally hard', 'Motorcycle', 'Jeepney (10× more momentum)', 'Neither moves', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'A fast lightweight boxer''s punch can still hurt a much heavier opponent because:', 'Gravity increases', 'Only mass matters', 'Mass doesn''t matter', 'High velocity gives the fist large momentum', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'pre_test', 'Why is falling on a soft mattress less painful than falling on concrete from the same height?', 'Concrete is colder', 'The mattress reduces your mass', 'The mattress increases stopping time, reducing force', 'Gravity is weaker on the mattress', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'When a cannon fires a cannonball forward, the cannon kicks backward. This is explained by:', 'Gravity', 'Conservation of momentum', 'Elastic collision', 'Magic', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'In a car crash, crumple zones at the front help mainly by:', 'Looking nice', 'Making the passenger cabin stop over a longer time', 'Reducing car mass', 'Making the car faster', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'Airbags work together with seatbelts because:', 'Seatbelts hold you while airbags spread the force and increase stopping time', 'Airbags alone stop you instantly', 'They look good', 'Seatbelts are useless alone', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'Two identical balls move at equal speed toward each other, collide, and bounce back at the same speed. This collision is:', 'Explosive', 'Very nearly elastic', 'Impossible', 'Perfectly inelastic', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'If you want to maximize the change in momentum of a kicked football, you should:', 'Tap it softly', 'Use a very light foot', 'Kick perpendicular to the motion', 'Apply the largest possible force for the longest possible time', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'Which correctly explains why momentum depends on BOTH mass and velocity?', 'A heavy slow object or a light fast object can both be equally hard to stop', 'Teacher said so', 'Mass cancels velocity', 'Only mass matters in collisions', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'In any collision—elastic or inelastic—which quantity is ALWAYS conserved?', 'Shape', 'Speed', 'Total linear momentum of the isolated system', 'Kinetic energy', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'A 1-kg clay blob moving at 5 m/s hits and sticks to a 4-kg stationary block. Afterward the combined mass moves at:', '0 m/s', '5 m/s', '1 m/s', '2.5 m/s', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'The main physics reason airbags reduce fatalities so dramatically is:', 'They block glass', 'They increase stopping time, reducing impact force', 'They cushion visually', 'They keep you awake', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'When you catch a fast raw egg without breaking it, you pull your hand backward while catching. This works because:', 'Gravity reverses', 'It increases the final velocity', 'It extends the contact time, reducing the average force', 'It reduces the egg''s mass', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'Two cars of equal mass and speed collide head-on and stop. Compared with one car hitting a wall at the same speed, the force on each driver is:', 'Essentially identical', 'Half', 'Double', 'Zero', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'Which correctly ranks the stopping force on an identical passenger from LOWEST to HIGHEST?', 'Dashboard → Airbag → Seatbelt', 'All equal', 'Airbag + Seatbelt → Seatbelt only → Dashboard/Windshield', 'Wall → Airbag + Seatbelt → Seatbelt only', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'In a student investigation with marbles of different masses rolled at different speeds, the pattern that will emerge is:', 'Only mass matters', 'Higher mass × higher speed produces greater momentum and greater impact', 'Only speed affects impact', 'No pattern', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'A firefighter turns on a powerful hose and feels it push backward strongly. This is a direct result of:', 'Water being heavy', 'Friction', 'Air pressure', 'Conservation of momentum', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000302', 1, 'post_test', 'The key difference between elastic and inelastic collisions is:', 'Momentum is conserved only in elastic collisions', 'Total kinetic energy is conserved only in elastic collisions; momentum is conserved in both', 'Inelastic collisions have no momentum', 'There are no forces in elastic collisions', 'B', 'Option B is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'The correct order of electricity from the power plant to your home is:', 'Meter → plant → lines', 'Power plant → step-up substation → transmission lines → step-down substation → distribution lines', 'Home → substation → plant', 'Transmission → plant → home', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'A device that changes AC voltage up or down very efficiently is a:', 'Transformer', 'Generator', 'Motor', 'Resistor', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Electricity is transmitted across the country at very high voltage mainly to:', 'Make electricity travel faster', 'Kill birds', 'Reduce energy lost as heat in transmission wires', 'Make it brighter', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Before entering houses, voltage is stepped down to about:', '12 V', '10,000 V', '1 V', '220–240 V', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'A generator converts:', 'Mechanical motion into electrical energy', 'Electricity into motion', 'Heat into light', 'Chemical energy into light', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'An electric motor converts:', 'Motion into electricity', 'Heat into sound', 'Electrical energy into mechanical motion', 'Light into electricity', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Which safety device melts and breaks the circuit if current becomes dangerously high?', 'Plug', 'Fuse', 'Wire', 'Switch', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Which reusable safety device automatically trips when too much current flows?', 'Fuse', 'Bulb', 'Outlet', 'Circuit breaker', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'The third round pin of a three-prong plug is connected to:', 'Ground (Earth) wire', 'Neutral wire', 'Live wire', 'Fuse', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'The device that measures your household''s electricity consumption is the:', 'Generator', 'Transformer', 'Kilowatt-hour (kWh) electric meter', 'Substation', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Step-up transformers at power plants:', 'Lower voltage for homes', 'Generate electricity', 'Raise voltage for long-distance transmission', 'Stop current', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Step-down transformers at substations:', 'Lower transmission voltage to safer distribution levels', 'Raise voltage', 'Store electricity', 'Burn waste', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'One major similarity between a motor and a generator is that:', 'Both plug directly into a wall outlet', 'Both have coils, magnets, and rotating parts', 'Both always use batteries', 'Both produce electricity', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'One major difference between a motor and a generator is:', 'A generator has no magnets', 'There is no difference', 'A motor has no coils', 'A motor uses electricity to produce motion, while a generator uses motion to produce electricity', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'pre_test', 'Octopus wiring is dangerous because:', 'Too much current can overheat wires and start a fire', 'It looks untidy', 'It uses more voltage', 'It breaks plugs', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Why should you never use water to put out an electrical fire?', 'It makes the fire hotter', 'Water conducts electricity and can cause electrocution', 'It damages the floor', 'It is expensive', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'What is the safest action if someone is being electrocuted while touching a live wire?', 'Turn off the main breaker first, then separate them using dry wood', 'Grab them with your bare hands', 'Pour water on the wire', 'Pull the wire with metal', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Why are transmission lines made with thick aluminum cables on tall towers?', 'Birds like them', 'Steel is cheaper', 'Aluminum is a good conductor, and tall towers provide safe clearance', 'They look better', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'A GFCI/ELCB outlet protects people by:', 'Increasing power', 'Making water safe', 'Lowering voltage', 'Detecting current leakage and shutting off the circuit quickly', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'The simplest way to reduce household electricity use is to:', 'Leave lights on', 'Use LED bulbs, switch off unused appliances, and use inverter appliances', 'Open the refrigerator often', 'Use more extension cords', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Why does high voltage reduce transmission losses?', 'Higher voltage means lower current, reducing I²R power loss', 'High voltage cools wires', 'Voltage removes resistance', 'Resistance disappears', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Which correctly describes the roles of NGCP and distribution utilities?', 'Distribution utilities generate electricity', 'Both perform the same job', 'NGCP handles high-voltage transmission, while distribution utilities deliver electricity to consumers', 'NGCP bills homes directly', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Inside a power plant generator, you would find:', 'Solar panels', 'Batteries charging', 'A turbine spinning an electromagnet inside coils to produce AC electricity', 'Chemical reactions', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Which statement about motors and generators is TRUE?', 'They share no parts', 'A generator requires electricity as input', 'A motor works without energy input', 'A DC motor can act as a generator when mechanically spun', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Why does the Philippines use alternating current (AC) for the national grid?', 'AC can be easily stepped up and down using transformers', 'Edison preferred AC', 'AC is always safer to touch', 'DC cannot run motors', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'A properly wired Philippine home has Live, Neutral, and Ground wires. Which statement is correct?', 'Neutral is always dangerous', 'Live carries 220 V, Neutral is the return path, and Ground is for safety', 'All three wires are the same', 'Ground carries normal current', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Why are circuit breakers preferred over fuses in modern homes?', 'They are cheaper', 'They look better', 'They use less metal', 'They can be reset after tripping and provide reliable protection', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Reducing household electricity use provides which benefit?', 'Lower electricity bills and reduced environmental impact', 'Only lower bills', 'Only global environmental benefits', 'No benefits', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Why are substations built at different voltage levels?', 'To waste money', 'To store electricity', 'To match the safest and most efficient voltage for each stage of distribution', 'To confuse consumers', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000303', 1, 'post_test', 'Which activity best models the journey of electricity from the power plant to homes?', 'Testing a fuse', 'Lighting a bulb with a battery', 'Spinning a motor', 'Small generator → step-up transformer → transmission wire → step-down transformer → bulb and', 'A', 'Option A is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'Energy sources that take millions of years to form and are gone once used are called:', 'Infinite', 'Non-renewable (fossil fuels)', 'Free', 'Renewable', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'Energy sources replenished naturally within a human lifetime are:', 'Renewable', 'Fossil fuels', 'Exhaustible', 'Non-renewable', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'The top source of electricity in the Philippines today is:', 'Solar', 'Wind', 'Coal', 'Tidal', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'The Philippines ranks second worldwide in which renewable energy source?', 'Oil', 'Coal', 'Solar', 'Geothermal', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'Burning fossil fuels releases large amounts of which greenhouse gas?', 'Carbon dioxide (CO₂)', 'Oxygen', 'Nitrogen', 'Hydrogen', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'Energy from falling or flowing water in dams like Angat and Magat is called:', 'Diesel', 'Coal', 'Hydroelectric power', 'Nuclear', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000304', 1, 'pre_test', 'Energy captured directly from sunlight using solar panels is:', 'Wind', 'Solar', 'Biomass', 'Geothermal', 'B', 'Option B is the correct answer.', true),
